<template><div class="biz-page"><PageHeader eyebrow="数据中心 · 商品盈利" title="商品毛利排行" description="查看单品毛利率及利润贡献度"/><section class="biz-card toolbar"><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD"/><el-button type="primary" :loading="loading" @click="load">查询</el-button></section><section class="biz-card"><el-table v-loading="loading" :data="rows" border><el-table-column type="index" label="排名" width="75"/><el-table-column prop="productName" label="商品" min-width="180"/><el-table-column prop="netSaleQuantity" label="净销量" width="100" align="right"/><el-table-column label="净销售额" width="130" align="right"><template #default="{row}">{{formatMoney(row.netSaleAmount)}}</template></el-table-column><el-table-column label="采购成本" width="130" align="right"><template #default="{row}">{{formatMoney(row.purchaseCost)}}</template></el-table-column><el-table-column label="毛利额" width="130" align="right"><template #default="{row}">{{formatMoney(row.grossProfit)}}</template></el-table-column><el-table-column label="毛利率" width="110" align="right"><template #default="{row}">{{percent(row.grossProfitRate)}}</template></el-table-column><el-table-column label="利润贡献度" width="125" align="right"><template #default="{row}">{{percent(row.profitContributionRate)}}</template></el-table-column></el-table></section></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{statisticsApi}from'../../api/statistics';import type{ProductProfitRank}from'../../types/statistics';import{formatMoney}from'../../utils/format';const now=new Date(),start=new Date();start.setDate(now.getDate()-29);const toDate=(d:Date)=>d.toISOString().slice(0,10);const range=ref([toDate(start),toDate(now)]),rows=ref<ProductProfitRank[]>([]),loading=ref(false);const percent=(v:number)=>`${(Number(v||0)*100).toFixed(2)}%`;async function load(){if(range.value.length!==2)return;loading.value=true;try{rows.value=await statisticsApi.getProductProfitRank({startDate:range.value[0],endDate:range.value[1]})??[]}finally{loading.value=false}}onMounted(load)</script><style scoped>.toolbar{margin-bottom:14px;display:flex;gap:10px}</style>
